// Run the fixture thousands of times and grade every price on the board.
//
// Each round is a fresh match generated by the fast engine, and every round is
// settled against every selection the bookmakers offer. What comes out is the
// distribution of what the simulation actually did — how often the home side
// won, how often there were over 2.5 goals, how often that exact 2:1 landed —
// next to the price the market is offering for it.

import { simulateMatch, mulberry32 } from "./fast-match-sim";
import type { OddsBoard } from "./odds-board";
import type { SimFormProfile, SimMatchExpectations } from "./sim-form-profile";
import {
  emptyAccumulator,
  settlementEv,
  settlementProbability,
  settleSelection,
  type SettlementAccumulator,
} from "./match-settlement";

export type MarketSimulationRow = {
  marketId: string;
  market: string;
  category: string;
  selection: string;
  counts: SettlementAccumulator;
  /** Stake-weighted chance the bet landed (pushes count half). */
  probability: number;
  pushRate: number;
  halfRate: number;
  bestBookmaker: string;
  bestPrice: number;
  books: number;
  implied: number;
  fair: number;
  /** 'raw' where the market cannot be de-vigged (player props, correct score). */
  fairSource: "normalised" | "raw";
  /** Mean profit per unit staked at the best price across the batch. */
  ev: number;
  /** Simulated probability minus the margin-free market probability. */
  edge: number;
};

/**
 * One line of the "did it happen as expected" read: what the market and the
 * clubs' own numbers asked for, what the played-out matches actually produced,
 * and which side of it that landed on.
 */
export type SimExpectationRow = {
  metric: string;
  /** 'goals' and 'corners' are per match, 'share' is a probability 0..1. */
  unit: "goals" | "corners" | "share";
  expected: number;
  simulated: number;
  /** simulated - expected, in the metric's own units. */
  delta: number;
  verdict: "over" | "under" | "as-expected";
};

export type OddsSimulationResult = {
  fixtureId: number;
  rounds: number;
  seed: number;
  elapsedMs: number;
  teams: [string, string];
  /** The market/form targets the played matches are being measured against. */
  expectations: SimMatchExpectations | null;
  /** Over / under / as expected, metric by metric. Empty without targets. */
  comparison: SimExpectationRow[];
  summary: {
    homeWin: number;
    draw: number;
    awayWin: number;
    averageGoals: number;
    averageHomeGoals: number;
    averageAwayGoals: number;
    averageFirstHalfGoals: number;
    averageSecondHalfGoals: number;
    btts: number;
    over25: number;
    over15: number;
    averageCorners: number;
    averageCards: number;
    averageShotsOnTarget: number;
    cleanSheetHome: number;
    cleanSheetAway: number;
    scorelines: { score: string; home: number; away: number; count: number }[];
  };
  markets: MarketSimulationRow[];
  untrackedMarkets: { market: string; selections: number }[];
};

// 100,000 rounds of the fast engine plus settlement of every selection costs a
// couple of seconds, which is what makes a six-figure batch practical.
const MAX_ROUNDS = 100_000;

/** How far from the target still counts as "as expected". */
const TOLERANCE = { goals: 0.15, corners: 0.4, share: 0.03 } as const;

function expectationRow(
  metric: string,
  unit: SimExpectationRow["unit"],
  expected: number | null | undefined,
  simulated: number,
): SimExpectationRow | null {
  if (expected === null || expected === undefined || !Number.isFinite(expected)) return null;
  const delta = simulated - expected;
  const verdict: SimExpectationRow["verdict"] =
    Math.abs(delta) <= TOLERANCE[unit] ? "as-expected" : delta > 0 ? "over" : "under";
  return { metric, unit, expected, simulated, delta, verdict };
}

function compareWithExpectations(
  expectations: SimMatchExpectations,
  played: {
    averageGoals: number;
    averageHomeGoals: number;
    averageAwayGoals: number;
    over25: number;
    btts: number;
    cleanSheetHome: number;
    cleanSheetAway: number;
    averageCorners: number;
  },
): SimExpectationRow[] {
  const rows = [
    expectationRow("Total goals", "goals", expectations.totalGoals, played.averageGoals),
    expectationRow("Home goals", "goals", expectations.homeGoals, played.averageHomeGoals),
    expectationRow("Away goals", "goals", expectations.awayGoals, played.averageAwayGoals),
    expectationRow("Over 2.5 goals", "share", expectations.over25, played.over25),
    expectationRow("Both teams score", "share", expectations.bothTeamsScore, played.btts),
    expectationRow("Home clean sheet", "share", expectations.homeCleanSheet, played.cleanSheetHome),
    expectationRow("Away clean sheet", "share", expectations.awayCleanSheet, played.cleanSheetAway),
    expectationRow(
      "Corners",
      "corners",
      expectations.homeCorners + expectations.awayCorners,
      played.averageCorners,
    ),
  ];
  return rows.filter((row): row is SimExpectationRow => row !== null);
}

export function simulateOddsBoard(
  board: OddsBoard,
  profile: SimFormProfile,
  options: { rounds: number; seed?: number; goalsPerMatch?: number },
): OddsSimulationResult {
  const started = Date.now();
  const rounds = Math.max(1, Math.min(MAX_ROUNDS, Math.round(options.rounds)));
  const seed = options.seed ?? Math.floor(Math.random() * 2 ** 31);
  const random = mulberry32(seed);

  // Every selection is settled the same way the played-out match is settled, so
  // the numbers here and the numbers after a watched match cannot drift apart.
  const tickets = board.markets.flatMap((market) =>
    market.selections.map((selection) => ({
      market,
      selection,
      counts: emptyAccumulator(),
    })),
  );

  const scorelineCounts = new Map<string, { home: number; away: number; count: number }>();
  let homeWins = 0;
  let draws = 0;
  let awayWins = 0;
  let goals = 0;
  let homeGoals = 0;
  let awayGoals = 0;
  let firstHalfGoals = 0;
  let secondHalfGoals = 0;
  let btts = 0;
  let over25 = 0;
  let over15 = 0;
  let corners = 0;
  let cards = 0;
  let shotsOnTarget = 0;
  let cleanSheetHome = 0;
  let cleanSheetAway = 0;
  const untracked = new Map<string, number>();

  for (let round = 0; round < rounds; round += 1) {
    const match = simulateMatch(profile, random, {
      goalsPerMatch: options.goalsPerMatch,
    });

    const total = match.home.goals + match.away.goals;
    goals += total;
    homeGoals += match.home.goals;
    awayGoals += match.away.goals;
    firstHalfGoals += match.halfTime.home + match.halfTime.away;
    secondHalfGoals += match.secondHalf.home + match.secondHalf.away;
    corners += match.home.corners + match.away.corners;
    cards += match.home.cards + match.away.cards;
    shotsOnTarget += match.home.shotsOnTarget + match.away.shotsOnTarget;
    if (match.home.goals === match.away.goals) draws += 1;
    else if (match.home.goals > match.away.goals) homeWins += 1;
    else awayWins += 1;
    if (match.home.goals > 0 && match.away.goals > 0) btts += 1;
    if (total > 2.5) over25 += 1;
    if (total > 1.5) over15 += 1;
    if (match.away.goals === 0) cleanSheetHome += 1;
    if (match.home.goals === 0) cleanSheetAway += 1;

    const score = `${match.home.goals}-${match.away.goals}`;
    const existing = scorelineCounts.get(score);
    if (existing) existing.count += 1;
    else {
      scorelineCounts.set(score, { home: match.home.goals, away: match.away.goals, count: 1 });
    }

    for (const ticket of tickets) {
      const settlement = settleSelection(
        ticket.market.name,
        ticket.selection.selection,
        match,
        { handicapLine: ticket.selection.handicapLine },
      );
      if (!settlement) {
        untracked.set(ticket.market.name, (untracked.get(ticket.market.name) ?? 0) + 1);
        continue;
      }
      ticket.counts[settlement.outcome] += 1;
    }
  }

  // A selection the engine cannot grade is reported as untracked rather than as
  // a loss, so the board never quietly claims a market was simulated.
  const untrackedMarkets = [...untracked.entries()].map(([market, selections]) => ({
    market,
    selections,
  }));

  const rows: MarketSimulationRow[] = tickets
    .filter((ticket) => {
      const total =
        ticket.counts.win +
        ticket.counts.lose +
        ticket.counts.push +
        ticket.counts["half-win"] +
        ticket.counts["half-loss"];
      return total > 0;
    })
    .map((ticket) => {
      const probability = settlementProbability(ticket.counts);
      const ev = settlementEv(ticket.counts, ticket.selection.best.price);
      return {
        marketId: ticket.market.marketId,
        market: ticket.market.name,
        category: ticket.market.category,
        selection: ticket.selection.selection,
        counts: ticket.counts,
        probability,
        pushRate: ticket.counts.push / rounds,
        halfRate: (ticket.counts["half-win"] + ticket.counts["half-loss"]) / rounds,
        bestBookmaker: ticket.selection.best.bookmaker,
        bestPrice: ticket.selection.best.price,
        books: ticket.selection.books,
        implied: ticket.selection.implied,
        fair: ticket.selection.fair,
        fairSource: ticket.selection.fairSource,
        ev,
        edge: probability - ticket.selection.fair,
      };
    })
    .sort((left, right) => right.edge - left.edge);

  return {
    fixtureId: board.fixtureId,
    rounds,
    seed,
    elapsedMs: Date.now() - started,
    teams: [profile.teams[0].name, profile.teams[1].name],
    expectations: profile.expectations ?? null,
    comparison: profile.expectations
      ? compareWithExpectations(profile.expectations, {
          averageGoals: goals / rounds,
          averageHomeGoals: homeGoals / rounds,
          averageAwayGoals: awayGoals / rounds,
          over25: over25 / rounds,
          btts: btts / rounds,
          cleanSheetHome: cleanSheetHome / rounds,
          cleanSheetAway: cleanSheetAway / rounds,
          averageCorners: corners / rounds,
        })
      : [],
    summary: {
      homeWin: homeWins / rounds,
      draw: draws / rounds,
      awayWin: awayWins / rounds,
      averageGoals: goals / rounds,
      averageHomeGoals: homeGoals / rounds,
      averageAwayGoals: awayGoals / rounds,
      averageFirstHalfGoals: firstHalfGoals / rounds,
      averageSecondHalfGoals: secondHalfGoals / rounds,
      btts: btts / rounds,
      over25: over25 / rounds,
      over15: over15 / rounds,
      averageCorners: corners / rounds,
      averageCards: cards / rounds,
      averageShotsOnTarget: shotsOnTarget / rounds,
      cleanSheetHome: cleanSheetHome / rounds,
      cleanSheetAway: cleanSheetAway / rounds,
      scorelines: [...scorelineCounts.values()]
        .sort((left, right) => right.count - left.count)
        .slice(0, 12)
        .map((entry) => ({
          score: `${entry.home}-${entry.away}`,
          home: entry.home,
          away: entry.away,
          count: entry.count,
        })),
    },
    markets: rows,
    untrackedMarkets,
  };
}
